curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for user in data['members']:
        if user.get('is_owner') or user.get('is_admin'):
            print(f\"ID: {user['id']}, Name: {user['real_name']}, Is Owner: {user.get('is_owner', False)}, Is Admin: {user.get('is_admin', False)}\")
else:
    print('Error:', data)
"

curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel,private_channel&limit=1000&exclude_archived=true" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(f\"ID: {ch['id']}, Name: {ch['name']}, Created: {ch['created']}, Is Private: {ch.get('is_private', False)}\")
else:
    print('Error:', data)
"
